  for insert with check (org_id = public.current_org());

grant insert on public.subscription_events to authenticated;


-- >>> 20261203000000_trial_on_signup.sql
-- Trial-on-signup + subscription lifecycle correctness.
-- 1. Widen org_subscriptions.status to the full lifecycle (the foundation CHECK
--    only allowed inactive/trialing/active/past_due/cancelled, so 'expired' and
--    'suspended' written by the platform workspace would have been rejected).
-- 2. create_organisation() now starts a trial so a brand-new company is never
--    stuck in status 'none' (which blocks every write).

-- ── 1. Full lifecycle status ──────────────────────────────────────────────────
do $$
declare c text;
begin
  select conname into c from pg_constraint
   where conrelid = 'public.org_subscriptions'::regclass and contype = 'c'
     and pg_get_constraintdef(oid) like '%status%';
  if c is not null then
    execute format('alter table public.org_subscriptions drop constraint %I', c);
  end if;
end $$;

alter table public.org_subscriptions
  add constraint org_subscriptions_status_check
  check (status in ('inactive','trialing','active','payment_pending','payment_failed',
                    'past_due','expired','suspended','cancelled'));

-- ── 2. Organisation onboarding starts a trial ────────────────────────────────
create or replace function public.create_organisation(p_name text, p_branch_name text, p_branch_code text)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid(); v_org uuid; v_br uuid; v_name text;
  v_plan uuid; v_days int; v_end timestamptz;
begin
  if v_uid is null then raise exception 'Sign in first' using errcode = '42501'; end if;
  if not exists (select 1 from auth.users where id = v_uid and email_confirmed_at is not null) then raise exception 'Confirm your email first'; end if;
  if exists (select 1 from profiles where id = v_uid and org_id is not null and is_approved) then raise exception 'You already belong to an organisation'; end if;
  -- First-run bootstrap (no approved member yet), or an allow-listed platform
  -- operator (legacy table or the platform_users scope). Everything else is
  -- invitation-only. Keyed on members rather than organisation rows so the demo
  -- tenant seeded by 0001_foundation cannot lock a fresh install out of setup.
  if exists (select 1 from profiles where org_id is not null and is_approved)
     and not exists (select 1 from platform_admins where user_id = v_uid)
     and not exists (select 1 from platform_users where user_id = v_uid and is_active) then
    raise exception 'Organisation creation is by invitation only' using errcode = '42501';
  end if;
  if length(trim(coalesce(p_name, ''))) < 2 or length(trim(coalesce(p_branch_name, ''))) < 2 or length(trim(coalesce(p_branch_code, ''))) < 1 then raise exception 'Organisation and branch names are required'; end if;

  insert into organizations (name) values (trim(p_name)) returning id into v_org;

  -- Trial: prefer an active public plan, fall back to any public plan, then any
  -- plan. A new organisation must never land in status 'none' (writes blocked).
  select id, trial_days into v_plan, v_days from public.billing_plans
    where is_public and active order by display_order limit 1;
  if v_plan is null then
    select id, trial_days into v_plan, v_days from public.billing_plans
      where is_public order by display_order limit 1;
  end if;
  if v_plan is null then
    select id, trial_days into v_plan, v_days from public.billing_plans
      order by display_order limit 1;
  end if;

  if v_plan is not null then
    v_end := now() + make_interval(days => coalesce(nullif(v_days, 0), 14));
    insert into public.org_subscriptions
      (org_id, plan_id, status, trial_ends_at, current_period_start, current_period_end, auto_renew)
    values (v_org, v_plan, 'trialing', v_end, now(), v_end, true);
    insert into public.subscription_events (org_id, event_type, payload, actor_id)
    values (v_org, 'subscription.trial_started',
            jsonb_build_object('plan_id', v_plan, 'trial_days', coalesce(v_days, 14)), v_uid);
  end if;

  insert into branches (org_id, code, name) values (v_org, upper(trim(p_branch_code)), trim(p_branch_name)) returning id into v_br;
  select coalesce(nullif(trim(raw_user_meta_data->>'full_name'), ''), split_part(email, '@', 1)) into v_name from auth.users where id = v_uid;
  insert into profiles (id, org_id, full_name, role_key, branch_id, is_approved, deactivated) values (v_uid, v_org, v_name, 'owner', v_br, true, false)
  on conflict (id) do update set org_id = v_org, role_key = 'owner', branch_id = v_br, is_approved = true, deactivated = false;
  return v_org;
end $$;

grant execute on function public.create_organisation(text, text, text) to authenticated;

revoke execute on function public.create_organisation(text, text, text) from anon, public;


-- >>> 20261205000000_checkout_billing.sql
-- 20261205000000_checkout_billing.sql
-- Subscription checkout (plan phase 3): link a Razorpay order to an invoice,
-- number tax invoices sequentially, make webhook events replay-safe, and hold the
-- platform's own GST identity.
--
-- Money stays privileged. subscription_invoices / subscription_payments keep their
-- SELECT-only RLS (20261201000000), so a tenant session can never insert an invoice
-- or mark one paid. Only server actions that have verified a Razorpay signature and
-- the webhook — both running through supabaseBilling() — can settle a payment.

-- 1. Invoice <-> Razorpay order linkage, plus the plan being purchased.
alter table public.subscription_invoices
  add column if not exists provider_order_id text,
  add column if not exists plan_id uuid references public.billing_plans(id),
  add column if not exists invoice_no text;

create unique index if not exists subscription_invoices_provider_order_key
  on public.subscription_invoices (provider_order_id)
  where provider_order_id is not null;

create unique index if not exists subscription_invoices_invoice_no_key
  on public.subscription_invoices (invoice_no)
  where invoice_no is not null;

create index if not exists subscription_invoices_org_status_idx
  on public.subscription_invoices (org_id, status, issued_at desc);

-- 2. Sequential GST invoice numbers: INV-YYYYMM-00001.
--    Assigned in the database so the checkout action and the webhook cannot drift.
create sequence if not exists public.subscription_invoice_seq;

create or replace function public.assign_subscription_invoice_no()
returns trigger
language plpgsql
set search_path = public as $$
begin
  if new.invoice_no is null or new.invoice_no = '' then
    new.invoice_no := 'INV-' || to_char(coalesce(new.issued_at, now()), 'YYYYMM')
                   || '-' || lpad(nextval('public.subscription_invoice_seq')::text, 5, '0');
  end if;
  return new;
end $$;

drop trigger if exists subscription_invoice_no on public.subscription_invoices;

create trigger subscription_invoice_no
  before insert on public.subscription_invoices
  for each row execute function public.assign_subscription_invoice_no();

-- 3. Webhook replay protection. provider_payment_id is already unique on
--    subscription_payments; this makes *any* Razorpay event idempotent, including
--    ones that do not carry a payment id.
alter table public.subscription_events
  add column if not exists provider_event_id text;

create unique index if not exists subscription_events_provider_event_key
  on public.subscription_events (provider_event_id)
  where provider_event_id is not null;

create index if not exists subscription_events_org_type_idx
  on public.subscription_events (org_id, event_type, created_at desc);

-- 4. The platform's own GST details. Not per-tenant: PowerOS issues these invoices,
--    so a single rate + GSTIN lives in platform_settings (platform admins only).
insert into public.platform_settings (key, value) values
  ('saas_gst_rate_bp', '1800'),
  ('saas_gstin', '""')
on conflict (key) do nothing;

-- billing_plans is a price catalogue: names, prices and limits are meant to be read
-- by every signed-in tenant. It ships with RLS on and no policy at all, so the app
-- was reading an empty plan list (only superuser test scripts could see the rows).
drop policy if exists billing_plans_read on public.billing_plans;

create policy billing_plans_read on public.billing_plans
  for select to authenticated using (true);

-- The GSTIN has to appear on the customer's own tax invoice, but platform_settings
-- itself is platform-admin only. This exposes just those two non-sensitive values.
create or replace function public.platform_billing_identity()
returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'gstin', coalesce((select value #>> '{}' from public.platform_settings where key = 'saas_gstin'), ''),
    'gst_rate_bp', coalesce((select (value #>> '{}')::int from public.platform_settings where key = 'saas_gst_rate_bp'), 1800)
  );
$$;

revoke execute on function public.platform_billing_identity() from public, anon;

grant execute on function public.platform_billing_identity() to authenticated, service_role;

-- 5. Settlement: the single place a payment becomes a paid invoice and an active
--    subscription. Idempotent, so the browser callback and the Razorpay webhook can
--    both call it and only the first one does the work.
--
--    EXECUTE is revoked from anon/authenticated on purpose. A tenant that could call
--    this directly could mark its own invoice paid without paying, so only the
--    service role reaches it — after the caller has verified a Razorpay signature.
create or replace function public.settle_subscription_payment(
  p_org_id uuid,
  p_invoice_id uuid,
  p_provider_order_id text,
  p_provider_payment_id text,
  p_amount_minor bigint,
  p_provider text default 'razorpay'
)
returns jsonb
language plpgsql
security definer
set search_path = public as $$
declare
  v_invoice public.subscription_invoices%rowtype;
  v_sub     public.org_subscriptions%rowtype;
  v_plan    public.billing_plans%rowtype;
  v_end     timestamptz;
begin
  select * into v_invoice
    from public.subscription_invoices
   where (p_invoice_id is not null and id = p_invoice_id)
      or (p_invoice_id is null and p_provider_order_id is not null and provider_order_id = p_provider_order_id)
   limit 1;
  if not found then
    raise exception 'subscription invoice not found';
  end if;
  if p_org_id is not null and v_invoice.org_id <> p_org_id then
    raise exception 'subscription invoice belongs to another organisation';
  end if;

  -- Replay / double callback: settle exactly once, report success either way.
  if v_invoice.status = 'paid' then
    return jsonb_build_object('ok', true, 'already_paid', true,
                              'invoice_id', v_invoice.id, 'invoice_no', v_invoice.invoice_no,
                              'org_id', v_invoice.org_id);
  end if;

  -- provider_payment_id is UNIQUE, so a concurrent replay lands here and is ignored.
  begin
    insert into public.subscription_payments
      (invoice_id, org_id, provider, provider_payment_id, status, amount_minor)
    values
      (v_invoice.id, v_invoice.org_id, p_provider, p_provider_payment_id, 'succeeded', p_amount_minor);
  exception when unique_violation then
    null;
  end;

  update public.subscription_invoices
     set status = 'paid', paid_at = coalesce(paid_at, now())
   where id = v_invoice.id;

  select * into v_plan from public.billing_plans where id = v_invoice.plan_id;
  if found then
    v_end := now() + case when v_plan.interval = 'year' then interval '1 year' else interval '1 month' end;

    select * into v_sub from public.org_subscriptions
     where org_id = v_invoice.org_id
     order by created_at desc limit 1;

    if not found then
      insert into public.org_subscriptions
        (org_id, plan_id, status, provider, provider_subscription_id,
         current_period_start, current_period_end, auto_renew)
      values
        (v_invoice.org_id, v_plan.id, 'active', p_provider, p_provider_payment_id, now(), v_end, true);
    else
      update public.org_subscriptions
         set plan_id = v_plan.id,
             status = 'active',
             provider = p_provider,
             provider_subscription_id = p_provider_payment_id,
             current_period_start = case when current_period_end is null or current_period_end < now()
                                         then now() else current_period_start end,
             current_period_end = greatest(coalesce(current_period_end, now()), now())
                                + case when v_plan.interval = 'year' then interval '1 year' else interval '1 month' end,
             auto_renew = true,
             cancelled_at = null,
             grace_ends_at = null,
             reactivated_at = case when status in ('cancelled','expired','suspended') then now() else reactivated_at end
       where id = v_sub.id;
    end if;
  end if;

  insert into public.subscription_events (org_id, event_type, payload)
  values (v_invoice.org_id, 'subscription.payment_succeeded', jsonb_build_object(
    'invoice_id', v_invoice.id,
    'invoice_no', v_invoice.invoice_no,
    'provider_order_id', v_invoice.provider_order_id,
    'provider_payment_id', p_provider_payment_id,
    'amount_minor', p_amount_minor,
    'plan_id', v_invoice.plan_id));

  return jsonb_build_object('ok', true, 'already_paid', false,
                            'invoice_id', v_invoice.id, 'invoice_no', v_invoice.invoice_no,
                            'org_id', v_invoice.org_id);
end $$;

revoke execute on function public.settle_subscription_payment(uuid, uuid, text, text, bigint, text)
  from public, anon, authenticated;

grant execute on function public.settle_subscription_payment(uuid, uuid, text, text, bigint, text)
  to service_role;


-- >>> 20261206000000_subscription_lifecycle.sql
-- 20261206000000_subscription_lifecycle.sql
-- Trial / renewal expiry (plan phase 3): one SQL function owns every lifecycle
-- transition so the cron, the edge function and a platform admin all behave
-- identically — and so the behaviour is testable straight from the DB test suite.
--
-- Nothing here ever deletes tenant data. An expired subscription only flips status:
-- reads, exports, billing and support stay open (plan non-goal: no data deletion).

create or replace function public.run_subscription_lifecycle()
returns jsonb
language plpgsql
security definer
set search_path = public as $$
declare
  v_trial_expired  int := 0;
  v_past_due      int := 0;
  v_grace_expired int := 0;
  v_cancelled     int := 0;
  n               int;
begin
  -- 1. Trial ran out. New signups always get a trial (20261203000000), so this is
  --    the transition that turns an abandoned signup into an expired tenant.
  with due as (
    update public.org_subscriptions
       set status = 'expired', updated_at = now()
     where status = 'trialing'
       and trial_ends_at is not null
       and trial_ends_at <= now()
    returning id, org_id, trial_ends_at
  )
  insert into public.subscription_events (org_id, event_type, payload)
  select org_id, 'subscription.trial_expired',
         jsonb_build_object('subscription_id', id, 'trial_ends_at', trial_ends_at)
    from due;
  get diagnostics n = row_count; v_trial_expired := n;

  -- 2. Paid period ended and auto-renew did not land -> grace window, not a hard stop.
  --    grace_days comes from the plan (default 7) so the platform sets the policy.
  update public.org_subscriptions s
     set status = 'past_due',
         grace_ends_at = now() + make_interval(days => coalesce(p.grace_days, 7)),
         updated_at = now()
    from public.billing_plans p
   where s.plan_id = p.id
     and s.status in ('active', 'payment_pending')
     and s.current_period_end is not null
     and s.current_period_end <= now()
     and (s.grace_ends_at is null or s.grace_ends_at <= now());
  get diagnostics n = row_count; v_past_due := n;

  -- Same transition for a subscription with no plan attached: fall back to 7 days.
  update public.org_subscriptions
     set status = 'past_due',
         grace_ends_at = now() + make_interval(days => 7),
         updated_at = now()
   where plan_id is null
     and status in ('active', 'payment_pending')
     and current_period_end is not null
     and current_period_end <= now()
     and (grace_ends_at is null or grace_ends_at <= now());
  get diagnostics n = row_count; v_past_due := v_past_due + n;

  -- 3. Grace window over -> expired. Writes stop, everything else stays reachable.
  with due as (
    update public.org_subscriptions
       set status = 'expired', grace_ends_at = null, updated_at = now()
     where status = 'past_due'
       and grace_ends_at is not null
       and grace_ends_at <= now()
    returning id, org_id, grace_ends_at
  )
  insert into public.subscription_events (org_id, event_type, payload)
  select org_id, 'subscription.expired',
         jsonb_build_object('subscription_id', id, 'grace_ended_at', grace_ends_at)
    from due;
  get diagnostics n = row_count; v_grace_expired := n;

  -- 4. Cancelled at the end of the period it already paid for.
  with due as (
    update public.org_subscriptions
       set status = 'expired', updated_at = now()
     where status = 'cancelled'
       and current_period_end is not null
       and current_period_end <= now()
    returning id, org_id, current_period_end
  )
  insert into public.subscription_events (org_id, event_type, payload)
  select org_id, 'subscription.expired',
         jsonb_build_object('subscription_id', id, 'period_end', current_period_end)
    from due;
  get diagnostics n = row_count; v_cancelled := n;

  return jsonb_build_object(
    'ok', true,
    'trial_expired', v_trial_expired,
    'moved_to_past_due', v_past_due,
    'grace_expired', v_grace_expired,
    'cancelled_expired', v_cancelled);
end $$;

-- Owned by the scheduler, not by tenants: triggering your own expiry early is
-- pointless but should not be reachable from a session either.
revoke execute on function public.run_subscription_lifecycle() from public, anon, authenticated;

grant execute on function public.run_subscription_lifecycle() to service_role;

-- Scheduled run. pg_cron is an extension the project owner enables from the
-- Supabase dashboard (same note as 0015_crm_automation.sql), so the schedule is
-- installed only when it is actually present — a fresh local `db reset` skips it
-- cleanly instead of failing. The edge function `subscription-lifecycle` is the
-- fallback/manual trigger for environments without pg_cron.
do $do$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    -- Re-running the migration must not stack duplicate schedules.
    if exists (select 1 from cron.job where jobname = 'subscription-lifecycle') then
      perform cron.unschedule('subscription-lifecycle');
    end if;
    perform cron.schedule('subscription-lifecycle', '*/15 * * * *',
                          $$select public.run_subscription_lifecycle()$$);
  end if;
end $do$;

